//! GUI screens: the boot chain (Mojang Studios loading -> title -> menus),
//! driven entirely by OFFICIAL data: every label comes from the jar's own
//! lang/en_us.json the runtime cache keeps (the generated/ -> runtime-load
//! migration's second lane: the table lives OFF the compiled source, the
//! loader below the only parser), every sprite from the official sprite
//! inventory, every splash from the jar's own texts/splashes.txt (the
//! migration's first lane — the same walk the splashes loader keeps).

use crate::gui::{Gui, GuiAssets};
use crate::math::{Mat4, Vec3};
use crate::raster::RenderCtx;

use mc_registry::generated::worldgen::Skybox;

/// THE SPLASHES' OWN LOADER (the generated/ -> runtime-load migration's
/// first lane — the pure-metadata table the compiled source no longer
/// carries): the jar's texts/splashes.txt the runtime cache keeps
/// VERBATIM, the parse law the old generator's own walk spoke — the
/// from_utf8_lossy read, the '\n' split, the '\r' trim, the empty
/// lines' filter. The line ORDER the pick law's own contract keeps
/// (the splitmix(seed) % len index the title golden's frame pins —
/// the same lines the old generated array held in the same order).
/// The absent file the honest empty list keeps — the title renders
/// the static fallback the empty-table law always spoke. The walk
/// speaks the boot's own roots: the workspace root the binary's cwd
/// keeps, the crate dir the cargo test cwd speaks one and two steps
/// below it.
fn parse_splashes(bytes: &[u8]) -> Vec<String> {
    String::from_utf8_lossy(bytes)
        .split('\n')
        .map(|l| l.trim_end_matches('\r').to_string())
        .filter(|l| !l.is_empty())
        .collect()
}

/// THE CARET'S OWN BYTE SEAT (the char index the string the insertion
/// byte answers — the `cursorPos` char coordinate the EditBox keeps,
/// the UTF-8 the byte lane the String stores: the nth char's byte
/// start the insert serves, the past-end the tail the same seat
/// answers).
fn caret_byte_index(s: &str, chars: usize) -> usize {
    s.char_indices()
        .nth(chars)
        .map(|(i, _)| i)
        .unwrap_or(s.len())
}

/// THE WORD'S OWN BOUNDARY (the vanilla EditBox getWordPosition walk
/// the `deleteWords` ±1 the border answers — the backward arm the
/// space run the skip then the non-space run the walk wears, the
/// forward arm the space seek then the run skip serves, the zero the
/// tail the bounds the same seat keeps, the ctrl arms the pair the
/// whole-word removal the trio answers).
fn word_boundary(s: &str, from: usize, forward: bool) -> usize {
    let chars: Vec<char> = s.chars().collect();
    let n = chars.len();
    let mut i = from.min(n);
    if forward {
        // the vanilla `indexOf(' ', i)` the seek then the run skip —
        // the -1 miss the length the same seat speaks
        while i < n && chars[i] != ' ' {
            i += 1;
        }
        while i < n && chars[i] == ' ' {
            i += 1;
        }
    } else {
        while i > 0 && chars[i - 1] == ' ' {
            i -= 1;
        }
        while i > 0 && chars[i - 1] != ' ' {
            i -= 1;
        }
    }
    i
}

/// THE CARET'S OWN X-BAND SEAT (the vanilla mouseClick walk the
/// `trimStringToWidth(text, i)` prefix the cursor length answers —
/// the clicked x the longest prefix whose accumulated width the
/// offset fits speaks, the left edge the zero wears, the past-tail
/// the len the same seat answers).
fn caret_char_index_at(text: &str, x_off: i32) -> usize {
    if x_off <= 0 {
        return 0;
    }
    let mut acc = 0i32;
    let mut count = 0usize;
    for c in text.chars() {
        let cw = crate::gui::font_text_width(&c.to_string());
        if acc + cw > x_off {
            break;
        }
        acc += cw;
        count += 1;
    }
    count
}

/// THE DISPLAY WINDOW'S OWN SYNC (the vanilla `setCursorPos` walk the
/// `displayPos` branch answers — the visible prefix the inner width
/// the `plainSubstrByWidth` trim keeps, the past-window caret the
/// display the seat pins right [`display = cursor - visLen`], the
/// before-window caret the display the cursor wears [`display =
/// cursor`]; the in-window caret the same display keeps — the short
/// text the zero the untouched arm answers).
fn display_window_sync(text: &str, display: &mut usize, cursor: usize, inner_w: i32) {
    let visible: String = text.chars().skip(*display).collect();
    let vis_len = caret_char_index_at(&visible, inner_w);
    if cursor > *display + vis_len {
        *display = cursor - vis_len;
    } else if cursor < *display {
        *display = cursor;
    }
}

/// THE ENTRY BOXES' OWN INNER WIDTH (the vanilla EditBox the
/// `getInnerWidth()` walk — the 200x20 `widget/text_field` box the
/// `-8` padding speaks, the drawn text the `x + 4` origin wears).
const ENTRY_BOX_INNER: i32 = 192;

/// THE ENTRY SELECTION'S OWN DELETE (the vanilla EditBox
/// `deleteSelection` walk the three entry boxes the 266 chat law
/// shares — the live [min(anchor, cursor), max) range the removal
/// answers, the cursor the lo seat re-parks, the anchor the collapse
/// wears; the collapsed/None pair the FALSE the caller's own arm
/// keeps — the first step the walk never wore).
fn entry_delete_selection(
    value: &mut String,
    cursor: &mut usize,
    anchor: &mut Option<usize>,
) -> bool {
    let Some(a) = *anchor else {
        return false;
    };
    if a == *cursor {
        // THE COLLAPSED PAIR'S OWN RE-PARK (the vanilla insertText the
        // setHighlightPos(cursorPos) tail wears — the banked-but-
        // collapsed seat the insert the same state keeps, the phantom
        // range the never-opens law keeps)
        *anchor = None;
        return false;
    }
    let lo = a.min(*cursor);
    let hi = a.max(*cursor);
    let start = caret_byte_index(value, lo);
    let end = caret_byte_index(value, hi);
    value.replace_range(start..end, "");
    *cursor = lo;
    *anchor = None;
    true
}

/// THE ENTRY SELECTION'S OWN SHIFT RIDE (the two-arg
/// `moveCursorTo(pos, hasShiftDown())` walk the arrows the trio
/// wears — the ±1 step the bounds clamp answers, the no-anchor
/// first ride the PRE-step cursor the anchor banks, the live
/// anchor the same seat the ride keeps [the vanilla field the
/// reset never wears]).
fn entry_shift_arrow(value: &str, cursor: &mut usize, anchor: &mut Option<usize>, left: bool) {
    let len = value.chars().count();
    let prev = *cursor;
    *cursor = if left {
        prev.saturating_sub(1)
    } else {
        (prev + 1).min(len)
    };
    if anchor.is_none() {
        *anchor = Some(prev);
    }
}

/// THE ENTRY SELECTION'S OWN SHIFT PARK (the 268/269 arms the
/// `moveCursorTo(0 / len, hasShiftDown())` walk the HOME/END the
/// trio wears — the bound park the same anchor law keeps, the
/// no-anchor first ride the old seat the anchor banks).
fn entry_shift_home_end(value: &str, cursor: &mut usize, anchor: &mut Option<usize>, end: bool) {
    let prev = *cursor;
    *cursor = if end { value.chars().count() } else { 0 };
    if anchor.is_none() {
        *anchor = Some(prev);
    }
}

/// THE ENTRY BOXES' OWN X-BAND SEAT (the 269 click walk the free
/// helper the mouse lanes share — the VISIBLE WINDOW the
/// `trimStringToWidth` law the two-step answers, the x the prefix
/// length + the displayPos the seat wears, the box padding the +4
/// the text origin speaks, the past-tail the clamp parks; the 267
/// `chat_click_seat` law the trio wears).
fn entry_click_seat(value: &str, display: usize, mx: i32, bx: i32) -> usize {
    let visible: String = value.chars().skip(display).collect();
    let vis_len = caret_char_index_at(&visible, ENTRY_BOX_INNER);
    let window: String = visible.chars().take(vis_len).collect();
    caret_char_index_at(&window, mx - (bx + 4)) + display
}

/// THE ENTRY BOXES' OWN WORD SEAT (the 268 chat law the
/// `chat_word_at` helper wears — the non-space seat the [start, end)
/// run banks, the space seat the empty pair keeps, the past-tail the
/// last word the same law answers).
fn entry_word_at(value: &str, seat: usize) -> (usize, usize) {
    let chars: Vec<char> = value.chars().collect();
    let n = chars.len();
    let lo = seat.min(n);
    if lo < n && !chars[lo].is_whitespace() {
        let mut start = lo;
        while start > 0 && !chars[start - 1].is_whitespace() {
            start -= 1;
        }
        let mut end = lo;
        while end < n && !chars[end].is_whitespace() {
            end += 1;
        }
        (start, end)
    } else if lo == n && lo > 0 && !chars[n - 1].is_whitespace() {
        let mut start = n;
        while start > 0 && !chars[start - 1].is_whitespace() {
            start -= 1;
        }
        (start, n)
    } else {
        (lo, lo) // the space seat the empty word wears
    }
}

/// THE STATS COUNTER'S OWN BANK (the vanilla StatsCounter walk — the
/// custom stats the client's own lanes feed: the tick the playTime
/// speaks, the jump the jumpFromGround banks, the death the die walk
/// counts, the movement the checkMovementStatistics cm law wears).
/// The fresh session the default keeps, the General tab the nonzero
/// rows serves.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct StatsCounter {
    /// `stat.playTime` — the in-world ticking ticks the update lane
    /// banks (the pause the same freeze the day clock wears)
    pub play_time: i64,
    /// `stat.sneakTime` — the crouched ticks the same lane counts
    pub sneak_time: i64,
    /// `stat.walkOneCm` — the on-ground walk centimetres the body's
    /// own cm law banks
    pub walk_cm: i64,
    /// `stat.sprintOneCm` — the sprint split the same lane wears
    pub sprint_cm: i64,
    /// `stat.swimOneCm` — the in-water split the same lane wears
    pub swim_cm: i64,
    /// `stat.jump` — the jumpFromGround events the tick drain takes
    pub jump: i64,
    /// `stat.deaths` — the die walk the actually_hurt verdict banks
    pub deaths: i64,
    /// `stat_type.minecraft.mined` — the block kinds the survival dig
    /// banks (the vanilla Stats.MINED the Block-keyed map wears; the
    /// BTreeMap the rows' stable order keeps)
    pub mined: std::collections::BTreeMap<u16, i64>,
    /// `stat_type.minecraft.crafted` — the item ids the result-take
    /// lanes bank (the vanilla Stats.ITEM_CRAFTED the Item-keyed map
    /// wears)
    pub crafted: std::collections::BTreeMap<i32, i64>,
    /// `stat_type.minecraft.killed` — the entity kinds the fist's own
    /// kills bank (the vanilla awardKillScore's
    /// awardStat(Stats.ENTITY_KILLED) walk the direct kill AND the
    /// sweep's own AoE verdict both wear; the entity id the stable
    /// BTreeMap order keeps)
    pub mob_kills: std::collections::BTreeMap<&'static str, i64>,
    /// `stat_type.minecraft.killed_by` — the killer words the die walk
    /// banks (the vanilla awardStat(Stats.ENTITY_KILLED_BY) the entity
    /// sources wear, the anonymous sources the None keeps; the display
    /// name the death message's %2$s arg carries)
    pub killed_by: std::collections::BTreeMap<String, i64>,
}

/// THE STATS FILE'S OWN DATA VERSION (the same 4903 pin the hotbar/
/// containers/options lanes wear — the `DataVersion` row the vanilla
/// save() walk appends, the load the honest keep answers).
pub const STATS_DATA_VERSION: i64 = 4903;

/// THE TIME STAT'S OWN FORMAT (the vanilla TimeFormatter walk — the
/// h:mm the tick count speaks: the hour the 72 000-tick day share,
/// the minute the 1 200-tick sweep the %60 fold wears).
pub fn stat_time_display(ticks: i64) -> String {
    let h = ticks / (20 * 60 * 60);
    let m = (ticks / (20 * 60)) % 60;
    format!("{}:{:02}", h, m)
}

/// THE DISTANCE STAT'S OWN FORMAT (the vanilla DistanceFormatter walk
/// — the cm the metre count speaks: the ≥100 000 cm the one-decimal
/// km wears, the rest the plain m answers).
pub fn stat_distance_display(cm: i64) -> String {
    if cm >= 100_000 {
        format!("{:.1} km", cm as f64 / 100_000.0)
    } else {
        format!("{} m", cm / 100)
    }
}

fn load_splashes() -> Vec<String> {
    for prefix in [
        "assets-cache/jar",
        "../assets-cache/jar",
        "../../assets-cache/jar",
    ] {
        if let Ok(bytes) =
            std::fs::read(std::path::Path::new(prefix).join("assets/minecraft/texts/splashes.txt"))
        {
            return parse_splashes(&bytes);
        }
    }
    Vec::new()
}

/// THE LANG TABLE'S OWN LOADER (the generated/ -> runtime-load migration's
/// second lane — the 552KB en_us table the compiled source no longer
/// carries): the jar's lang/en_us.json the runtime cache keeps VERBATIM,
/// the parse law the old generator's own collect walk spoke — the flat
/// keys the direct entries, the nested objects the dotted-key join, the
/// non-string entries the skip law keeps, the serde_json read the shape
/// the jar's own file speaks. The absent/broken file the honest empty map
/// keeps — the inline fallback every call site carries answers the
/// cache-absent boot (the CI's pre-generate test job the same arm walks).
/// The roots the splash loader's own walk speaks: the workspace root the
/// binary's cwd keeps, the crate dir the cargo test cwd one and two steps
/// below. The OnceLock the load-once law keeps — tr's own signature the
/// Option<&'static str> the call sites and the goldens pin.
fn parse_lang(bytes: &[u8]) -> std::collections::BTreeMap<String, String> {
    let v: serde_json::Value = match serde_json::from_slice(bytes) {
        Ok(v) => v,
        Err(_) => return std::collections::BTreeMap::new(),
    };
    let obj = match v.as_object() {
        Some(o) => o,
        None => return std::collections::BTreeMap::new(),
    };
    let mut map = std::collections::BTreeMap::new();
    lang_collect("", obj, &mut map);
    map
}

fn lang_collect(
    prefix: &str,
    obj: &serde_json::Map<String, serde_json::Value>,
    out: &mut std::collections::BTreeMap<String, String>,
) {
    for (k, v) in obj {
        let key = if prefix.is_empty() {
            k.clone()
        } else {
            format!("{prefix}.{k}")
        };
        match v {
            serde_json::Value::String(s) => {
                out.insert(key, s.clone());
            }
            serde_json::Value::Object(inner) => lang_collect(&key, inner, out),
            _ => {} // non-string entries are not translatable text
        }
    }
}

fn load_lang() -> std::collections::BTreeMap<String, String> {
    for prefix in [
        "assets-cache/jar",
        "../assets-cache/jar",
        "../../assets-cache/jar",
    ] {
        if let Ok(bytes) =
            std::fs::read(std::path::Path::new(prefix).join("assets/minecraft/lang/en_us.json"))
        {
            return parse_lang(&bytes);
        }
    }
    std::collections::BTreeMap::new()
}

/// Translate a GUI key (exact vanilla lookup, the loaded table's own law).
fn tr(key: &str) -> Option<&'static str> {
    static LANG: std::sync::OnceLock<std::collections::BTreeMap<String, String>> =
        std::sync::OnceLock::new();
    LANG.get_or_init(load_lang).get(key).map(|s| s.as_str())
}

/// THE CONTAINER TITLE'S OWN DECODE (the OpenScreen word's Component —
/// vanilla's text-component tree the anonymous-root compound the parse
/// retains wears; `ComponentSerialization.TRUSTED_STREAM_CODEC`'s own
/// shape). The rows the walk renders:
/// - a `text` row the literal speaks (the anvil rename's own bytes);
/// - a `translate` row the lang table answers — a MISSING row answers
///   with the key ITSELF (the `Language.getOrDefault` law the chat
///   decoration's own lookup keeps), the container.dropper row the
///   live dropper window's default name rides;
/// - an `extra` list the siblings ride (the base text the compound's
///   own rows keep, the children concatenated after — the sibling law);
/// - a bare list the concatenated children speak.
/// The forms the walk never understands (scalars, styled compounds with
/// neither row) stay `None` — the default lang row the canvas banks
/// (the honest fallback, the `container.dispenser` default the live
/// lane's own law keeps). The `%s` argument forms the walk never
/// substitutes (the container rows carry none — the gap the doc names).
fn decode_container_title(bytes: &[u8]) -> Option<String> {
    use mc_protocol::nbt::Nbt;
    fn text_of(node: &Nbt) -> Option<String> {
        match node {
            Nbt::String(s) => Some(s.clone()),
            Nbt::List(items) => {
                if items.is_empty() {
                    return None;
                }
                let mut out = String::new();
                for it in items {
                    out.push_str(&text_of(it).unwrap_or_default());
                }
                Some(out)
            }
            Nbt::Compound(_) => {
                let base = if let Some(t) = node.get("text").and_then(|v| v.as_str()) {
                    Some(t.to_string())
                } else if let Some(key) = node.get("translate").and_then(|v| v.as_str()) {
                    // the getOrDefault law: the missing row answers its key
                    Some(tr(key).unwrap_or(key).to_string())
                } else {
                    // a textless compound renders only its extras (the
                    // vanilla default the empty text keeps)
                    node.get("extra").map(|_| String::new())
                };
                match (base, node.get("extra").and_then(|v| v.as_list())) {
                    (Some(b), Some(extra)) if !extra.is_empty() => {
                        let mut out = b;
                        for it in extra {
                            out.push_str(&text_of(it).unwrap_or_default());
                        }
                        Some(out)
                    }
                    (Some(b), _) => Some(b),
                    (None, _) => None,
                }
            }
            _ => None,
        }
    }
    let mut c: &[u8] = bytes;
    let root = mc_protocol::nbt::read_network_nbt(&mut c).ok()?;
    text_of(&root)
}

/// THE CHAT DECORATION'S OWN FORMAT (vanilla `TranslatableContents`
/// .decompose's walk — the pattern the en_us lang table's entries carry,
/// each `%s` the NEXT argument replaces; the positional `%N$s` forms the
/// general [`format_positional`] walk answers, the lang table's own
/// `%1$s`/`%2$s` rows the same law wears). A MISSING key answers with the
/// key ITSELF — the `Language.getOrDefault` law the real client's own
/// lookup keeps (an untranslatable server-custom key displays as its
/// key, the args the format never speaks).
pub(crate) fn format_chat_decoration(key: &str, args: &[&str]) -> String {
    let Some(fmt) = tr(key) else {
        return key.to_string();
    };
    format_positional(fmt, args)
}

/// THE POSITIONAL WALK (vanilla `TranslatableContents.decompose`'s
/// template walk — the SAME law the chat decorations and the lang
/// table's `%N$s` rows share: the sequential `%s` the NEXT argument
/// replaces, the positional `%N$s` the N-th (1-based) argument answers
/// and the sequential counter the form never advances (the decompose
/// walk's own counter law — ONLY the plain `%s` branch the `counter[0]++`
/// consumes, the positional read the counter never touches: the mixed
/// template `%1$s %s` the args `[a, b]` the `a a` pair answers — the
/// plain `%s` the FIRST non-positional slot fills), the
/// `%%` the literal percent keeps, the malformed `%` (the trailing one,
/// the unknown escape's) the literal the walk emits — the next char the
/// honest walk serves as itself). A MISSING argument answers `""` — the
/// `args.get().unwrap_or("")` law the sequential lane already wears.
/// THE SIBLING RESET rides both substitutions (the template's literals
/// wear the TEMPLATE's style, never the argument's: the §-codes the arg
/// carried the §r closes).
/// THE FLOAT'S OWN JAVA WORD (vanilla `Float.toString` the
/// `commands.time.rate` feedback's second arg wears): the integral
/// floats the trailing `.0` keep (`2.0` — Rust's bare `2` never
/// speaks), the fractional values the shortest round-trip display
/// renders (`0.5`). The practical command range (1.0e-5..=1000.0)
/// the two laws cover — the scientific-notation extremes the
/// `Float.toString` switches to never seat this command's bounds.
pub(crate) fn java_float_string(v: f32) -> String {
    if v.fract() == 0.0 && v.abs() < 1.0e7 {
        format!("{:.1}", v)
    } else {
        format!("{}", v)
    }
}

pub(crate) fn format_positional(fmt: &str, args: &[&str]) -> String {
    let mut out = String::with_capacity(fmt.len());
    let mut chars = fmt.chars().peekable();
    let mut arg_i = 0usize;
    while let Some(c) = chars.next() {
        if c != '%' {
            out.push(c);
            continue;
        }
        // THE PERCENT'S OWN BRANCH (the decompose walk's char pairs)
        match chars.peek().copied() {
            Some('%') => {
                chars.next();
                out.push('%');
            }
            Some('s') => {
                chars.next();
                let arg = args.get(arg_i).copied().unwrap_or("");
                push_positional_arg(&mut out, arg);
                arg_i += 1;
            }
            Some(d) if d.is_ascii_digit() => {
                // THE POSITIONAL FORM — the digit run the `%N$s` shape
                // keeps (the multi-digit index the run answers, the
                // `$s` pair the form's own tail wears)
                let mut idx = String::new();
                while let Some(d2) = chars.peek().copied() {
                    if !d2.is_ascii_digit() {
                        break;
                    }
                    idx.push(d2);
                    chars.next();
                }
                if chars.peek() == Some(&'$') {
                    chars.next();
                    if chars.peek() == Some(&'s') {
                        chars.next();
                        let n: usize = idx.parse().unwrap_or(0);
                        let arg = if n >= 1 {
                            args.get(n - 1).copied().unwrap_or("")
                        } else {
                            // THE ZERO INDEX — `%0$s` the 1-based law
                            // refuses, the empty answer keeps
                            ""
                        };
                        push_positional_arg(&mut out, arg);
                    } else {
                        // THE MALFORMED TAIL (`%1$x`) — the literal
                        // percent the walk emits, the digits + the
                        // dollar the honest walk re-speaks
                        out.push('%');
                        out.push_str(&idx);
                        out.push('$');
                    }
                } else {
                    // THE MALFORMED SHAPE (`%1x`) — the literal percent,
                    // the digits the next chars themselves answer
                    out.push('%');
                    out.push_str(&idx);
                }
            }
            _ => {
                // THE TRAILING PERCENT — the literal the walk keeps
                out.push('%');
            }
        }
    }
    out
}

/// THE ARG'S OWN PUSH (the sibling-reset law both forms share — the
/// code-bearing arg the §r close speaks, the code-less arg the state
/// never left).
fn push_positional_arg(out: &mut String, arg: &str) {
    out.push_str(arg);
    if arg.contains('\u{a7}') {
        out.push_str("\u{a7}r");
    }
}

/// THE DECORATION LINE'S OWN FILL (the parameter walk BOTH chat
/// packets' display answers — the bound's `parameters` list names each
/// %s's SOURCE: "sender" the bound's sender name, "target" the bound's
/// target name (the absent target the empty string fills), "content"
/// the message text; the unknown parameter the empty string fills — the
/// vanilla walk's own null-fold). The format key + the filled args the
/// display line answers.
pub(crate) fn format_decoration_line(
    chat_key: &str,
    parameters: &[String],
    sender_name: &str,
    target_name: Option<&str>,
    content: &str,
) -> String {
    let args: Vec<&str> = parameters
        .iter()
        .map(|p| match p.as_str() {
            "sender" => sender_name,
            "target" => target_name.unwrap_or(""),
            "content" => content,
            _ => "",
        })
        .collect();
    format_chat_decoration(chat_key, &args)
}

/// THE PLAYER CHAT LINE'S OWN WALK (vanilla `ChatType.Bound.decorate`'s
/// consumer tail — the parameter walk the shared
/// [`format_decoration_line`] speaks).
pub(crate) fn format_player_chat_line(m: &mc_protocol::play::PlayerChatMessage) -> String {
    format_decoration_line(
        &m.chat_key,
        &m.parameters,
        &m.sender_name,
        m.target_name.as_deref(),
        &m.content,
    )
}

pub const WHITE: [f32; 3] = [1.0, 1.0, 1.0];
/// THE SPRINT WINDOW'S OWN SPAN (26.2 Options <init>'s audited
/// OptionInstance('options.sprintWindow', IntRange(0, 10), 7) — the
/// double-tap-W window the LocalPlayer.aiStep's sprintTriggerTime
/// re-arms each fresh first W press, the ticks the second press may
/// arrive within; the option's slider the client's no-settings-UI
/// world keeps at its own 7 default).
