                    b.prev_x = b.x;
                    b.prev_y = b.y;
                    b.prev_z = b.z;
                    b.x = fx;
                    b.y = fy;
                    b.z = fz;
                    b.vx = 0.0;
                    b.vy = 0.0;
                    b.vz = 0.0;
                    b.on_ground = false;
                    b.horizontal_collision = false;
                    b.forward = 0.0;
                    b.left = 0.0;
                    b.jumping = false;
                    b.sprinting = false;
                    b.want_crouch = false;
