                                    && m.x <= ax + 1.0 + crate::mob::ZOMBIE_FOLLOW_RANGE
                                    && m.y >= ay - crate::mob::ALERT_RANGE_Y
                                    && m.y <= ay + 1.0 + crate::mob::ALERT_RANGE_Y
                                    && m.z >= az - crate::mob::ZOMBIE_FOLLOW_RANGE
                                    && m.z <= az + 1.0 + crate::mob::ZOMBIE_FOLLOW_RANGE;
