    /// THE CLICK-ENCHANT WALK (javap 26.2 EnchantmentMenu
    /// `clickMenuButton(Player, int)` the exact 154-code walk banks —
    /// scripts/jar_work/click_enchant_exact_337.txt the full stream
    /// speaks): the id gate the `id < 0 || id >= costs.length` pair
    /// keeps [the out-of-range press the
    /// Util.logAndPauseIfInIde arm the offline silence wears], the
    /// lapis guard the `isEmpty() || getCount() < i` the `i = id + 1`
    /// pair answers [pc 56-82 — the infinite-materials arm the
    /// creative gate keeps], the cost guard the `costs[id] <= 0 ||
    /// itemstack.isEmpty()` the pc 83-96 pair speaks, the xp guard
    /// the `experienceLevel < i || experienceLevel < costs[id]` the
    /// pc 99-125 max-of-two law wears [the same creative arm], then
    /// the SUCCESS walk the `lambda$clickMenuButton$0` banks: the
    /// onEnchantmentPerformed the xp spend AND the seed draw speaks
    /// [pc 33-38 — `giveExperienceLevels(-i)` the give_levels floor
    /// law wears, `enchantmentSeed = random.nextInt()` the
    /// player-random draw the enchant_rng answers], the lapis the
    /// `consume(i)` shrink the count-0 the `setItem(1, EMPTY)` the
    /// empty-pair law keeps [pc 122-146], the costs re-roll the
    /// slotsChanged walk the fresh seed answers [pc 192-208 — the
    /// `enchantmentSeed.set(getEnchantmentSeed())` the same field the
    /// menu's DataSlot mirrors, the slotsChanged the
    /// `random.setSeed(seed)` the rolls answer]. THE ENCHANT
    /// APPLICATION the item-stack's own data-model round keeps [pc
    /// 41-119 — the transmute/enchant walk the (id, count) pair the
    /// enchantment storage never carries, the stack-extension round
    /// the harness waits; the getEnchantmentList-empty gate the same
    /// round answers — vanilla spends NOTHING on a non-enchantable
    /// item].
    pub fn click_enchant_option(&mut self, id: usize) -> bool {
        if id >= 3 {
            return false; // pc 0-27 — the costs.length gate the log arm keeps
        }
        let i = id + 1;
        let lapis = self.enchant_slots.get(1).copied().unwrap_or((0, 0));
        let item = self.enchant_slots.first().copied().unwrap_or((0, 0));
        let creative = self.game_mode == GameMode::Creative;
        if (lapis.1 == 0 || lapis.1 < i as i32) && !creative {
            return false; // pc 56-82 — the empty-or-short pair the creative arm answers
        }
        if self.enchanting_costs[id] <= 0 || item.1 == 0 {
            return false; // pc 83-96 — the dead-row or empty-item pair
        }
        if !creative && (self.xp.level < i as i32 || self.xp.level < self.enchanting_costs[id]) {
            return false; // pc 99-125 — the max-of-two xp law the creative arm answers
        }
        // THE LIST BUILD + THE EMPTY GATE (the lambda's pc 0-30 walk
        // the dev-196 round banks — the getEnchantmentList the seed
        // + row the pick list answers, the EMPTY list the
        // NOTHING-spent return wears: vanilla spends NO xp and NO
        // lapis on a non-enchantable item [the 337 walk's
        // unconditional spend the honest stop answers])
        let list = self.enchant_pick_list(id, item.0, self.enchanting_costs[id]);
        if list.is_empty() {
            return false; // lambda pc 23-30 — the empty gate
        }
        // THE SUCCESS WALK (the lambda$clickMenuButton$0 the exact
        // order banks — the xp spend + the seed draw FIRST, the book
        // transmute the enchanted-book stack wears, the instances the
        // store rides, the lapis consume the empty-pair law keeps,
        // the re-roll the tail answers)
        self.xp.give_levels(-(i as i32));
        self.enchant_seed = self.enchant_rng.next_unbounded();
        // THE BOOK TRANSMUTE (the lambda pc 41-68 — the
        // transmuteCopy(ENCHANTED_BOOK) the count keeps, the setItem
        // (0, stack) the slot wears)
        if Self::enchant_item_name(item.0) == "book" {
            if let Some(eb) = mc_registry::item_id_by_name("enchanted_book") {
                self.enchant_slots[0] = (eb, item.1);
            }
        }
        // THE ENCHANT LOOP (the lambda pc 73-119 — the stack.enchant
        // walk the instances the store's own component lane wears)
        self.enchant_comps[0] = list;
        let left = lapis.1 - i as i32;
        self.enchant_slots[1] = if left > 0 {
            (lapis.0, left)
        } else {
            (0, 0) // pc 130-146 — the count-0 the setItem(1, EMPTY) law
        };
        self.enchant_costs_refresh();
        self.enchant_use_voice();
        true
    }

    /// THE USE VOICE'S OWN EMIT (the lambda tail pc 211-241 — the
    /// `playSound(null, pos, ENCHANTMENT_TABLE_USE, BLOCKS, 1.0F,
    /// 0.9F + rand * 0.1F)` walk the table pos the listener's ear the
    /// same attenuation the container voices wear)
    fn enchant_use_voice(&mut self) {
        let Some(pos) = self.enchanting_table_pos else {
            return;
        };
        let ear = self.body.as_ref().map(|b| (b.x, b.y + b.eye_height(), b.z));
        let yaw = self.listener_yaw();
        let (x, y, z) = (
            f64::from(pos.0) + 0.5,
            f64::from(pos.1) + 0.5,
            f64::from(pos.2) + 0.5,
        );
        let dist = ear_distance(ear, x, y, z);
        let pan = ear_pan(ear, yaw, x, y, z);
        self.sounds.play_enchant_use_voice_at(self.frame, dist, pan);
    }

    /// THE BREW FINISH'S OWN VOICE (the dev-338 round — javap 26.2
    /// LevelEventHandler.levelEvent case 1035 the 26.2 jar serves:
    /// `playLocalSound(pos, BREWING_STAND_BREW, BLOCKS, 1.0F, 1.0F,
    /// false)` — the FIXED volume and pitch lane (no randoms, the
    /// brewing's own deadpan pour), the stand pos the listener's ear
    /// the same attenuation the container voices wear)
    fn brew_finish_voice(&mut self, pos: (i32, i32, i32)) {
        let ear = self.body.as_ref().map(|b| (b.x, b.y + b.eye_height(), b.z));
        let yaw = self.listener_yaw();
        let (x, y, z) = (
            f64::from(pos.0) + 0.5,
            f64::from(pos.1) + 0.5,
            f64::from(pos.2) + 0.5,
        );
        let dist = ear_distance(ear, x, y, z);
        let pan = ear_pan(ear, yaw, x, y, z);
        self.sounds.play_brew_voice_at(self.frame, dist, pan);
    }

    /// the right-press on the placed enchanting table the OFFLINE
    /// world answers — the window the table's own 176x166 canvas
    /// opens, the TRANSIENT pair the SimpleContainer(2) the fresh
    /// seats lay [the vanilla menu the table's own BE never keeps —
    /// NO per-cell store the chest's map law never wears, the close
    /// the pair the ride-home walk returns]).
    pub fn open_enchanting_for(&mut self, pos: (i32, i32, i32)) {
        self.enter_world();
        // THE STALE CELL'S OWN RELEASE FIRST (the chest open walk's
        // own law the brewing lane wears)
        self.barrel_lid_released();
        // the OFFLINE stand-in: the live lane's flag stays down (the
        // enchanting door the wire session never wears)
        self.chest_is_live = false;
        self.chest_mirror.clear();
        // THE TRANSIENT PAIR (the EnchantmentMenu's own SimpleContainer(2)
        // the fresh open lays — the item 0 the lapis 1 the menu
        // numbering banks)
        self.enchant_slots = vec![(0, 0), (0, 0)];
        self.enchant_carried = (0, 0);
        // THE SPELL WALK'S OWN SEAT + COSTS (the dev-195 round — the
        // pos the scan reads, the empty item the zero costs the
        // slotsChanged's own isEmpty gate keeps: the fresh open the
        // fresh scan lays, the reopen the re-scan the transient
        // menu's own law wears)
        self.enchanting_table_pos = Some(pos);
        self.enchant_costs_refresh();
        // the player's own rows the REAL inventory projects (the
        // menu's addStandardInventorySlots(8, 84) the mirror rows the
        // same projection keeps)
        self.enchant_mirror_sync_from_inventory();
        // THE STORE'S OWN MIRROR LOAD (the dev-196 round — the
        // inventory_enchants the SAME numbering the mirror rows
        // project: the enchanted stacks the reopen the store's own
        // rows answer, the transient pair + the carried the fresh
        // empty stores keep)
        for menu in 0..self.enchant_comps.len() {
            match Self::enchant_menu_to_inventory(menu) {
                Some(idx) => {
                    self.enchant_comps[menu] = self.inventory_enchants[idx].clone()
                }
                None => self.enchant_comps[menu].clear(),
            }
        }
        // THE FAMILY'S OWN VOICE (the counter law the chest walk keeps
        // — the enchanting kind the vanilla's own silence arm the
        // emit call returns)
        self.container_voice_emit(true);
        self.open(ScreenKind::Enchanting);
    }

    /// THE ENCHANTING TABLE'S OWN MIRROR SYNC (the chest's own law — the
    /// projection the inventory IS: the main rows the items 9..35
    /// speak, the hotbar row the items 0..8, the fresh rows EVERY
    /// mutation re-syncs).
    pub fn enchant_mirror_sync_from_inventory(&mut self) {
        if self.enchant_mirror.len() != 36 {
            self.enchant_mirror.resize(36, (0, 0));
        }
        for i in 0..27 {
            self.enchant_mirror[i] = self.inventory.items[9 + i];
        }
        for i in 0..9 {
            self.enchant_mirror[27 + i] = self.inventory.items[i];
        }
        self.hotbar_slots = self.inventory.hotbar();
    }

    /// THE ENCHANTING TABLE'S OWN CLOSE (the vanilla Escape/E on the
    /// enchanting table's screen — the chest's own close walk the
    /// carried return speaks, the EnchantmentMenu.removed()'s
    /// clearContainer the PAIR home returns: the same-item merges, the
    /// first-empty pass, the full store the remainder drops — the
    /// close_brewing shape, the NO store flush the table's BE never
    /// keeps), the screen back to the world. THE ENCHANTED STACKS'
    /// OWN LAW (the dev-196 round — the component-bearing pair the
    /// merge lane never rides [the vanilla components the stack
    /// identity carries, the same-id plain stack the different
    /// component set refuses], the FIRST-EMPTY placement the store's
    /// own rows answer, the inventory_enchants the same 36-slot
    /// numbering keys).
    pub fn close_enchanting(&mut self, back: ScreenKind) {
        // THE MIRROR ROWS' OWN STORE RIDE FIRST (the write-through
        // projection the pairs already keep — the SAME numbering the
        // stores ride: the menu seat's component rows the inventory
        // cell answers; the FLUSH the carried/pair rides PRECEDES —
        // the first-empty placements the mirror cells may take, the
        // fresh store the ride's own write wins)
        for menu in 0..self.enchant_comps.len() {
            if let Some(idx) = Self::enchant_menu_to_inventory(menu) {
                self.inventory_enchants[idx] = self.enchant_comps[menu].clone();
            }
        }
        // THE CARRIED'S OWN HOME RIDE (the vanilla removed()'s
        // placeItemBackInInventory walk — the close_brewing shape;
        // the enchanted carried the merge lane never rides — the
        // first-empty placement the store answers)
        if self.enchant_carried.1 > 0 {
            let (id, count) = self.enchant_carried;
            let enchanted = !self.enchant_comps[38].is_empty();
            let mut rest = count;
            if !enchanted {
                for it in self.inventory.items.iter_mut() {
                    if rest == 0 {
                        break;
                    }
                    if it.1 > 0 && it.0 == id && it.1 < crate::world_view::item_max_stack(id) {
                        let take = (crate::world_view::item_max_stack(id) - it.1).min(rest);
                        it.1 += take;
                        rest -= take;
                    }
                }
            }
            for idx in 0..self.inventory.items.len() {
                if rest == 0 {
                    break;
                }
                if self.inventory.items[idx].1 <= 0 {
                    self.inventory.items[idx] = (id, rest);
                    self.inventory_enchants[idx] = self.enchant_comps[38].clone();
                    rest = 0;
                }
            }
            if rest > 0 {
                self.spawn_drop_at_player(id, rest);
            }
            self.enchant_carried = (0, 0);
            self.enchant_comps[38].clear();
        }
        // THE PAIR'S OWN HOME RIDE (the removed()'s clearContainer walk —
        // the transient seats the close NEVER banks: each held stack
        // the same merge/first-empty/drop lane returns; the enchanted
        // seat the first-empty placement the store's own rows answer)
        for seat in 0..2usize {
            let (id, count) = self.enchant_slots[seat];
            if count <= 0 {
                continue;
            }
            let enchanted = !self.enchant_comps[seat].is_empty();
            let mut rest = count;
            if !enchanted {
                for it in self.inventory.items.iter_mut() {
                    if rest == 0 {
                        break;
                    }
                    if it.1 > 0 && it.0 == id && it.1 < crate::world_view::item_max_stack(id) {
                        let take = (crate::world_view::item_max_stack(id) - it.1).min(rest);
                        it.1 += take;
                        rest -= take;
                    }
                }
            }
            for idx in 0..self.inventory.items.len() {
                if rest == 0 {
                    break;
                }
                if self.inventory.items[idx].1 <= 0 {
                    self.inventory.items[idx] = (id, rest);
                    self.inventory_enchants[idx] = self.enchant_comps[seat].clone();
                    rest = 0;
                }
            }
            if rest > 0 {
                self.spawn_drop_at_player(id, rest);
            }
            self.enchant_slots[seat] = (0, 0);
        }
        self.container_removed_rode = true; // the removed law rode
        self.open(back);
    }

