    /// THE DIRECT CONNECTION'S OWN CLICK FOCUS (the EditBox
    /// .mouseClicked walk the debug search box's law shares — the
    /// inside click the `setFocused(true)` re-arm serves, the TRUE the
    /// consumed click returns (the caller's buttons walk the return
    /// skips — the box the footer pair never overlaps), the outside
    /// click the FALSE the caller the focus-transfer answers (the
    /// widget the focus loses, the buttons the click's own action
    /// serves)). The rect the render's own bank the walk reads (the
    /// same store freshness the buttons' own rects wear).
    pub fn on_direct_box_click(&mut self, mx: i32, my: i32) -> bool {
        if self.screen != ScreenKind::DirectConnect {
            return false;
        }
        let (bx, by, bw, bh) = self.direct_box_rect;
        let inside = mx >= bx && mx < bx + bw && my >= by && my < by + bh;
        self.direct_focus = inside;
        // THE DRAG ARM'S OWN BANK (the vanilla `setDragging(flag &&
        // button == 0)` walk the inside press serves — the arm the held
        // frames the drag walk answers, the outside the false disarms)
        self.direct_drag_armed = inside;
        if inside {
            // THE CARET'S OWN X-BAND (the vanilla mouseClick walk the
            // clicked char the cursor positions — the VISIBLE WINDOW
            // the `trimStringToWidth(value.substring(displayPos))` law
            // the two-step answers, the x the prefix length + the
            // displayPos the seat wears, the box padding the +4 the
            // render's own text origin speaks)
            let seat = entry_click_seat(&self.direct_address, self.direct_display, mx, bx);
            // THE DOUBLE'S OWN WINDOW (the 268 chat law the EditBox
            // lastClickTime walk serves — the <250ms window the climb
            // answers: the live selection the next click the WHOLE
            // value [the selectText(0, len) law], the collapsed pair
            // the word select the cursor=end/anchor=start wears, the
            // empty word the None anchor keeps, the third click the
            // all re-answers, the stale window the plain seek re-wears)
            let now = std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .map(|d| d.as_millis())
                .unwrap_or(0);
            if let Some((t, _)) = self.direct_last_click {
                if now.saturating_sub(t) < 250 {
                    let live = matches!(self.direct_highlight, Some(h) if h != self.direct_cursor);
                    if live {
                        // the whole value the climb answers (the 269
                        // selectAll law the same park wears)
                        self.direct_cursor = self.direct_address.chars().count();
                        self.direct_highlight = Some(0);
                    } else {
                        let (ws, we) = entry_word_at(&self.direct_address, seat);
                        self.direct_cursor = we;
                        self.direct_highlight = if ws == we { None } else { Some(ws) };
                    }
                    self.direct_last_click = Some((now, seat));
                    display_window_sync(
                        &self.direct_address,
                        &mut self.direct_display,
                        self.direct_cursor,
                        ENTRY_BOX_INNER,
                    );
                    return true;
                }
            }
            // the plain click the `moveCursorTo(pos)` one-arg law the
            // anchor collapses (the 266 law the box wears) — the
            // consumed press the stamp + the DRAG ARM banks
            self.direct_last_click = Some((now, seat));
            self.direct_highlight = None;
            self.direct_cursor = seat;
            display_window_sync(
                &self.direct_address,
                &mut self.direct_display,
                self.direct_cursor,
                ENTRY_BOX_INNER,
            );
        }
        inside
    }

    /// THE ENTRY BOXES' OWN SHIFT CLICK (the 267 chat law the EditBox
    /// mouseClick's hasShiftDown branch wears — the two-arg
    /// `moveCursorTo(pos, true)` walk the anchor preserves: the
    /// no-anchor first ride the PRE-CLICK cursor the anchor banks, the
    /// cursor the clicked seat wears, the focus the plain click's
    /// re-arm keeps, the outside click the false the caller's buttons
    /// walk keeps).
    pub fn on_direct_box_shift_click(&mut self, mx: i32, my: i32) -> bool {
        if self.screen != ScreenKind::DirectConnect {
            return false;
        }
        let (bx, by, bw, bh) = self.direct_box_rect;
        // THE FOCUS TRANSFER'S OWN WALK (the plain click's law the
        // outside click wears — the losing box's focus the vanilla
        // walk drops, the selection the same honesty keeps)
        let inside = mx >= bx && mx < bx + bw && my >= by && my < by + bh;
        self.direct_focus = inside;
        if !inside {
            return false; // the outside click the band never owns
        }
        let seat = entry_click_seat(&self.direct_address, self.direct_display, mx, bx);
        if self.direct_highlight.is_none() {
            self.direct_highlight = Some(self.direct_cursor);
        }
        self.direct_cursor = seat;
        display_window_sync(
            &self.direct_address,
            &mut self.direct_display,
            self.direct_cursor,
            ENTRY_BOX_INNER,
        );
        true
    }

    /// THE ENTRY BOXES' OWN DRAG (the 267 chat law the EditBox.onDrag
