    /// THE KILLED ENTITY'S OWN DISPLAY NAME (lambda$kill$0's
    /// `getDisplayName()` arg walk): the player the own name wears,
    /// the mob the entity-type lang key the en_us table answers
    /// (`entity.minecraft.pig` = "Pig") — the missing key the
    /// getOrDefault law the key ITSELF renders.
    fn kill_target_display_name(&self, target: &KillTarget) -> String {
        match target {
            KillTarget::Player => PLAYER_NAME.to_string(),
            KillTarget::Mob(i) => {
                // THE LANG KEY'S OWN SHAPE (entity.minecraft.pig — the
                // registry id's colon the DOT the key section
                // replaces)
                let key = format!(
                    "entity.{}",
                    self.mobs
                        .get(*i)
                        .map(|m| mob_kind_entity_id(m.kind))
                        .unwrap_or("minecraft:mob")
                        .replace(':', ".")
                );
                tr(&key).unwrap_or(key.as_str()).to_string()
            }
        }
    }

    /// THE EFFECT WORD'S OWN PARSE (javap `ResourceArgument.resource`
    /// — the ResourceLocation reader the registry lookup rides): the
    /// bare path the default namespace wears (`speed` the
    /// `minecraft:speed` key becomes), the namespaced word the
    /// verbatim lookup answers, the unknown key the registry-miss
    /// failure keeps. THE CHARSET (the ResourceLocation's own law —
    /// the [a-z0-9._-/] body the ':' separator joins; the upper-case
    /// or odd-char word the reader the parse failure answers).
    fn parse_effect_word(word: &str) -> Option<i32> {
        let normalized = match word.split_once(':') {
            Some((ns, path)) => {
                if ns.is_empty() || path.is_empty() {
                    return None;
                }
                word.to_string()
            }
            None => format!("minecraft:{word}"),
        };
        let charset_ok = normalized.chars().all(|c| {
            c.is_ascii_lowercase() || c.is_ascii_digit() || matches!(c, '.' | '_' | '-' | '/' | ':')
        });
        if !charset_ok {
            return None;
        }
        crate::effects::effect_id_by_name(&normalized)
    }

    /// THE INT ARG'S OWN PARSE (javap `IntegerArgumentType` — the
    /// reader the range verdicts wear: the non-numeric word the parse
    /// failure keeps, the below-min / above-max the too-low/too-high
    /// failure answers).
    fn parse_int_arg(word: &str, min: i32, max: i32) -> Option<i32> {
        word.parse::<i64>().ok().and_then(|n| {
            if n < min as i64 || n > max as i64 {
                None
            } else {
                Some(n as i32)
            }
        })
    }

    /// THE BOOL ARG'S OWN PARSE (javap `BoolArgumentType.bool` — the
    /// exact `true`/`false` words the reader answers, everything else
    /// the parse failure keeps).
    fn parse_bool_arg(word: &str) -> Option<bool> {
        match word {
            "true" => Some(true),
            "false" => Some(false),
            _ => None,
        }
    }

    /// THE EFFECT'S OWN DISPLAY NAME (javap `MobEffect.getDisplayName`
    /// — the descriptionId translatable the en_us table answers: the
    /// `effect.minecraft.speed` key the "Speed" row wears; the missing
    /// key the getOrDefault law the KEY ITSELF renders).
    fn effect_display_name(effect_id: i32) -> String {
        let Some(name) =
            mc_registry::generated::mob_effects::MOB_EFFECT_ORDER.get(effect_id as usize)
        else {
            return effect_id.to_string();
        };
        let key = format!("effect.{}", name.replace(':', "."));
        tr(&key).unwrap_or(key.as_str()).to_string()
    }

    /// THE GIVE WALK (javap `EffectCommands.giveEffect` — the
    /// collection loop the LivingEntity instances the addEffect dose
    /// rides, the count the true returns bank): the PLAYER target the
    /// own store speaks, the MOB target the kind's canBeAffected gate
    /// the undead refusal wears and the per-mob store the same
    /// insert-or-update law answers.
    fn effect_give(
        &mut self,
        targets: &[KillTarget],
        effect_id: i32,
        duration: i32,
        amplifier: i32,
        flags: u8,
    ) -> usize {
        let mut count = 0;
        for target in targets {
            let applied = match target {
                KillTarget::Player => self
                    .effects
                    .add_effect(effect_id, amplifier, duration, flags),
                KillTarget::Mob(i) => match self.mobs.get_mut(*i) {
                    None => false,
                    Some(mob) => {
                        // THE CAN-BE-AFFECTED GATE (javap
                        // `LivingEntity.canBeAffected` pcs 52-87 —
                        // the IGNORES_POISON_AND_REGEN member the
                        // REGENERATION/POISON instance refuses; the
                        // offline roster's undead the
                        // zombie/skeleton kinds speak, every other
                        // kind the accept law keeps)
                        if crate::effects::undead_ignores(effect_id)
                            && matches!(
                                mob.kind,
                                crate::mob::MobKind::Zombie | crate::mob::MobKind::Skeleton
                            )
                        {
                            false
                        } else {
                            mob.effects
                                .add_effect(effect_id, amplifier, duration, flags)
                        }
                    }
                },
            };
            if applied {
                count += 1;
            }
        }
        count
    }

    /// THE CLEAR WALK (javap `EffectCommands.clearEffects` /
    /// `clearEffect` — the collection loop the
    /// `removeAllEffects()`/`removeEffect(effect)` true returns
    /// count): the player's and the mobs' own stores the same
    /// removal law answers, the effect-less body the false return
    /// the count never banks.
    fn effect_clear(&mut self, targets: &[KillTarget], effect_id: Option<i32>) -> usize {
        let mut count = 0;
        for target in targets {
            let removed = match target {
                KillTarget::Player => match effect_id {
                    None => self.effects.remove_all(),
                    Some(id) => self.effects.remove_effect(id),
                },
                KillTarget::Mob(i) => match self.mobs.get_mut(*i) {
                    None => false,
                    Some(mob) => match effect_id {
                        None => mob.effects.remove_all(),
                        Some(id) => mob.effects.remove_effect(id),
                    },
                },
            };
            if removed {
                count += 1;
            }
        }
        count
    }

    /// THE GIVE COMMAND'S OWN WALK (the seven `give` arms the tree
    /// shares): the parse the selector + effect words keep, the
    /// duration the giveEffect law computes, the count the feedback
    /// wears and the empty count the red exception answers.
    fn effect_give_command(
        &mut self,
        targets_word: &str,
        effect_word: &str,
        seconds: Option<i32>,
        amplifier: i32,
        hide_particles: bool,
    ) {
        let Some(targets) = self.selector_kill_targets(targets_word) else {
            self.push_local_command_error();
            return;
        };
        let Some(effect_id) = Self::parse_effect_word(effect_word) else {
            self.push_local_command_error();
            return;
        };
        // THE DURATION LAW (javap giveEffect pcs 14-80 — the
        // instantaneous body the seconds the TICKS speaks, the
        // non-instant the *20 fold wears, the -1 sentinel the
        // `infinite` literal carries; the no-seconds arm the 600
        // default the instant body the 1-tick default answers)
        let duration = match seconds {
            None => {
                if crate::effects::is_instantaneous(effect_id) {
                    1
                } else {
                    600
                }
            }
            Some(n) if crate::effects::is_instantaneous(effect_id) => n,
            Some(-1) => -1,
            Some(n) => n * 20,
        };
        // THE FLAGS' OWN PACK (javap giveEffect pc 134 — the 5-arg
        // `MobEffectInstance` ctor the ambient=false,
        // visible=!hideParticles pair speaks; the 6-arg tail the
        // showIcon the SAME visible word the ctor's own
        // delegation answers — pcs 60-69 the (.., visible, visible)
        // fold)
        let flags = if hide_particles {
            0
        } else {
            crate::effects::DEFAULT_EFFECT_FLAGS
        };
        let count = self.effect_give(&targets, effect_id, duration, amplifier, flags);
        if count == 0 {
            // THE FAILED VERDICT (javap giveEffect pcs 162-173 —
            // ERROR_GIVE_FAILED the red exception renders, the
            // commands.effect.give.failed translatable the lang
            // table carries)
            let msg = tr("commands.effect.give.failed").unwrap_or(
                "Unable to apply this effect (target is either immune to effects, or has something stronger)",
            );
            self.push_chat_message(format!("\u{a7}c{msg}"));
            return;
        }
        // THE FEEDBACK (lambda$giveEffect$0/$1 — the size-1
        // COLLECTION the single key's entity name wears, every OTHER
        // size the multiple key's count carries)
        let effect_name = Self::effect_display_name(effect_id);
        if targets.len() == 1 {
            let name = self.kill_target_display_name(&targets[0]);
            let msg = format_positional(
                tr("commands.effect.give.success.single").unwrap_or("Applied effect %s to %s"),
                &[&effect_name, &name],
            );
            self.push_chat_message(msg);
        } else {
            let msg = format_positional(
                tr("commands.effect.give.success.multiple")
                    .unwrap_or("Applied effect %s to %s targets"),
                &[&effect_name, &targets.len().to_string()],
            );
            self.push_chat_message(msg);
        }
    }

    /// THE CLEAR COMMAND'S OWN WALK (the three `clear` arms the tree
    /// shares): the no-targets walk the SOURCE entity the
    /// single-player collection answers, the no-effect walk the
    /// every-removal lane runs, the specific walk the one effect
    /// removes; the zero count the failed verdicts the red
    /// exception wears.
    fn effect_clear_command(&mut self, targets_word: Option<&str>, effect_word: Option<&str>) {
        let targets: Vec<KillTarget> = match targets_word {
            None => vec![KillTarget::Player],
            Some(word) => {
                let Some(targets) = self.selector_kill_targets(word) else {
                    self.push_local_command_error();
                    return;
                };
                targets
            }
        };
        let effect_id = match effect_word {
            None => None,
            Some(word) => match Self::parse_effect_word(word) {
                None => {
                    self.push_local_command_error();
                    return;
                }
                Some(id) => Some(id),
            },
        };
        let count = self.effect_clear(&targets, effect_id);
        if count == 0 {
            // THE FAILED VERDICTS (javap clearEffects pcs 58-68 /
            // clearEffect pcs 73-84 — ERROR_CLEAR_EVERYTHING_FAILED
            // and ERROR_CLEAR_SPECIFIC_FAILED the red exceptions
            // render)
            let (key, fallback) = if effect_id.is_none() {
                (
                    "commands.effect.clear.everything.failed",
                    "Target has no effects to remove",
                )
            } else {
                (
                    "commands.effect.clear.specific.failed",
                    "Target doesn't have the requested effect",
                )
            };
            let msg = tr(key).unwrap_or(fallback);
            self.push_chat_message(format!("\u{a7}c{msg}"));
            return;
        }
        // THE FEEDBACK (lambda$clearEffects$0/$1, lambda$clearEffect$0
        // /$1 — the collection-size law the give walk wears)
        let effect_name = effect_id.map(Self::effect_display_name);
        if targets.len() == 1 {
            let name = self.kill_target_display_name(&targets[0]);
            let msg = match &effect_name {
                None => format_positional(
                    tr("commands.effect.clear.everything.success.single")
                        .unwrap_or("Removed every effect from %s"),
                    &[&name],
                ),
                Some(effect) => format_positional(
                    tr("commands.effect.clear.specific.success.single")
                        .unwrap_or("Removed effect %s from %s"),
                    &[effect, &name],
                ),
            };
            self.push_chat_message(msg);
        } else {
            let msg = match &effect_name {
                None => format_positional(
                    tr("commands.effect.clear.everything.success.multiple")
                        .unwrap_or("Removed every effect from %s targets"),
                    &[&targets.len().to_string()],
                ),
                Some(effect) => format_positional(
                    tr("commands.effect.clear.specific.success.multiple")
                        .unwrap_or("Removed effect %s from %s targets"),
                    &[effect, &targets.len().to_string()],
                ),
            };
            self.push_chat_message(msg);
        }
    }

    /// THE ENTITY SELECTOR'S OWN TARGET WALK (EntityArgument.entities'
    /// `getEntities` find walk — the source the offline dispatch's
    /// own player speaks, the world the selector's predicate runs
    /// against): the parse the [`parse_entity_selector_word`] walk
    /// keeps, the match the world's own roster answers. THE HEADS:
    /// `@s`/`@p`/`@a`/`@r` the single-player source the same ONE
    /// player each answers (the nearest/all/random-player lanes the
    /// multiplayer rosters alone widen — the offline walk the honest
    /// single roster keeps), `@e` the world's own entities — the
    /// mobs AND the player both ride (the vanilla all-entities
    /// query's own shape). THE TYPE FILTER the predicate's own law
    /// keeps: the positive ids the set the membership demands, the
    /// `!`-negated ids the exclusion wears, the empty-positive set
    /// the negations-alone the match keeps. THE DISTANCE FILTER
    /// (javap `EntitySelector` lambda$getPredicate$2 — the SQUARED
    /// feet distance the squared bounds answer:
    /// `range.matchesSqr(entity.distanceToSqr(source))`, the linear
    /// block law the square-fold equivalence keeps). THE SORT + THE
    /// LIMIT (javap `EntitySelector.sortAndLimit` — the size>1 list
    /// the order BiConsumer sorts, the subList the maxResults cap
    /// truncates: the nearest the ascending distanceToSqr comparator
    /// wears, the furthest the swapped args the descending law keeps,
    /// the random the Collections.shuffle backward walk speaks, the
    /// arbitrary the noop answers).
    fn selector_kill_targets(&mut self, word: &str) -> Option<Vec<KillTarget>> {
        let parsed = parse_entity_selector_word(word)?;
        // THE TYPE FILTER (the predicate's own law — the positive ids
        // the membership set demands, the negated ids the exclusion
        // wears, the empty-positive set the negations-alone the match
        // keeps: excluded-by-none AND (no-positives OR included))
        let type_filter = |id: Option<&str>| -> bool {
            let mut any_positive = false;
            let mut included = false;
            let mut excluded = false;
            for (negated, filter_id) in &parsed.types {
                let hit = id == Some(filter_id.as_str());
                if *negated {
                    if hit {
                        excluded = true;
                    }
                } else {
                    any_positive = true;
                    if hit {
                        included = true;
                    }
                }
            }
            !excluded && (!any_positive || included)
        };
        // THE SOURCE POSITION (the command source's own feet — the
        // distanceToSqr arg the distance predicate and the
        // nearest/furthest orders read)
        let source = self.body.as_ref().map(|b| (b.x, b.y, b.z));
        let squared = |x: f64, y: f64, z: f64| -> f64 {
            match source {
                Some((sx, sy, sz)) => {
                    (x - sx) * (x - sx) + (y - sy) * (y - sy) + (z - sz) * (z - sz)
                }
                // THE SOURCELESS WALK (the degenerate no-body state the
                // offline dispatch never serves — the no-filter lane the
                // arbitrary order keeps)
                None => 0.0,
            }
        };
        // THE DISTANCE PREDICATE (lambda$getPredicate$2's matchesSqr
        // walk — the squared bounds the squared distance answers; the
        // filter the parse carries the no-range lane the always-true
        // keeps, the sourceless state the no-match wears)
        let distance_ok = |x: f64, y: f64, z: f64| -> bool {
            match parsed.distance {
                None => true,
                Some((min, max)) => {
                    // THE SQUARED BOUNDS (the optional side the square
                    // NEVER touches — the empty min the vanilla square
                    // walk keeps: -inf squared the +inf poison the
                    // unbounded side refuses, the guard the -inf the
                    // -inf carries)
                    let min2 = if min == f64::NEG_INFINITY {
                        f64::NEG_INFINITY
                    } else {
                        min * min
                    };
                    let d2 = squared(x, y, z);
                    d2 >= min2 && d2 <= max * max
                }
            }
        };
        // THE CANDIDATE COLLECTION (the predicates the world's roster
        // filter, the order the sortAndLimit walk applies, the limit
        // the maxResults cap wears)
        let mut candidates: Vec<(KillTarget, f64)> = Vec::new();
        // THE MOBS' OWN WALK (the world's entity roster — the type
        // filter the kind's own registry id the predicate reads; the
        // all-entities head alone the mob roster answers)
        for (i, mob) in self.mobs.iter().enumerate() {
            if parsed.head.all_entities()
                && type_filter(Some(mob_kind_entity_id(mob.kind)))
                && distance_ok(mob.x, mob.y, mob.z)
            {
                let d2 = squared(mob.x, mob.y, mob.z);
                candidates.push((KillTarget::Mob(i), d2));
            }
        }
        // THE PLAYER'S OWN LANE (the single-player roster — every
        // head the player answers: the @s source, the @p/@a/@r
        // player lanes, and the @e all-entities walk the player
        // includes; the type AND the distance filters the same
        // predicates run — the source IS the player the zero distance
        // the in-range law answers)
        if type_filter(Some("player")) {
            let (px, py, pz) = source.unwrap_or((0.0, 0.0, 0.0));
            if distance_ok(px, py, pz) {
                let d2 = squared(px, py, pz);
                candidates.push((KillTarget::Player, d2));
            }
        }
        // THE SORT (EntitySelectorParser's ORDER_* BiConsumers — the
        // comparator the Doubles.compare law keeps, the shuffle the
        // world's own mob RNG stream draws, the singleton the order
        // skips — sortAndLimit's size>1 gate)
        let size = candidates.len();
        match parsed.sort {
            Some(SelectorSort::Nearest) if size > 1 => {
                candidates.sort_by(|a, b| a.1.total_cmp(&b.1));
            }
            Some(SelectorSort::Furthest) if size > 1 => {
                candidates.sort_by(|a, b| b.1.total_cmp(&a.1));
            }
            Some(SelectorSort::Random) if size > 1 => {
                // THE SHUFFLE (Collections.shuffle's backward
                // Fisher-Yates — the bound draw `nextInt(i+1)` the
                // modulo walk mirrors, the swap the draw's index wears)
                for i in (1..size).rev() {
                    let j = (self.mob_rng.next() % (i as u64 + 1)) as usize;
                    candidates.swap(i, j);
                }
            }
            _ => {}
        }
        // THE LIMIT (sortAndLimit's subList cap — the maxResults the
        // size min wears)
        if let Some(l) = parsed.limit {
            candidates.truncate(l);
        }
        Some(candidates.into_iter().map(|(t, _)| t).collect())
    }

    /// THE GAME MODE WORD'S OWN PARSE (GameModeArgument's byName walk
    /// — the exact lowercase names the GameType enum carries, the
    /// unknown word the ERROR_INVALID verdict keeps).
    fn parse_game_mode_word(word: &str) -> Option<GameMode> {
        match word {
            "survival" => Some(GameMode::Survival),
            "creative" => Some(GameMode::Creative),
            "adventure" => Some(GameMode::Adventure),
            "spectator" => Some(GameMode::Spectator),
            _ => None,
        }
    }

    /// THE VEC3'S OWN PARSE (the Vec3Argument's plain-number form —
    /// the three doubles the whitespace split carries, the finite
    /// verdict the NaN/Inf rejection keeps, the `~` relative form the
    /// honest absence documents).
    fn parse_triple(xs: &str, ys: &str, zs: &str) -> Option<(f64, f64, f64)> {
        let (x, y, z) = (
            xs.parse::<f64>().ok()?,
            ys.parse::<f64>().ok()?,
            zs.parse::<f64>().ok()?,
        );
        if x.is_finite() && y.is_finite() && z.is_finite() {
            Some((x, y, z))
        } else {
            None
        }
    }

    /// THE ITEM ARGUMENT'S OWN RESOLUTION (the ItemArgument's
    /// `minecraft:<name>` id walk — the namespace prefix the strip
    /// keeps, the registry name the wire order's own vocabulary
    /// answers, the unknown name the honest None keeps).
    fn parse_item_id(name: &str) -> Option<i32> {
        let name = name.strip_prefix("minecraft:").unwrap_or(name);
        mc_registry::item_id_by_name(name)
    }

    /// THE TIME ARGUMENT'S OWN PARSE (javap TimeArgument.parse — the
    /// float head the StringReader.readFloat consumes, the optional
    /// unit word the readUnquotedString rides, the UNITS map the
    /// static init fills: `d`=24000, `s`=20, `t`=1 — the bare number
    /// the ticks the getOrDefault(1) keeps — and the `Math.round` the
    /// float-to-ticks fold wears). The FLOOR the registered minimum
    /// speaks (the `set` lane's `TimeArgument.time()` the zero floor
    /// carries, the `add` lane's `time(-2147483648)` the negatives
    /// allows, the weather `duration`'s `time(1)` the one-tick floor
    /// wears) — the below-floor verdict the
    /// `argument.time.tick_count_too_low` exception the parse throws,
    /// the client's generic red the offline lane renders.
    fn parse_time_arg(word: &str, min: i64) -> Option<i64> {
        // THE UNIT SPLIT (the parse's own two reads — the float head,
        // the trailing unit letters the remaining reader carries)
        let split = word.len()
            - word
                .chars()
                .rev()
                .take_while(|c| c.is_ascii_alphabetic())
                .map(|c| c.len_utf8())
                .sum::<usize>();
        let (head, unit) = word.split_at(split);
        let mult: i64 = match unit {
            "" | "t" => 1,
            "s" => 20,
            "d" => 24000,
            // THE INVALID UNIT (the UNITS map's miss — the
            // `argument.time.invalid_unit` exception the parse throws)
            _ => return None,
        };
        let value: f32 = head.parse().ok()?;
        if !value.is_finite() {
            return None;
        }
        let ticks = (value * mult as f32).round() as i64;
        if ticks < min {
            return None;
        }
        Some(ticks)
    }

    /// THE WEATHER WORD'S OWN RESOLUTION (javap WeatherCommand's
    /// `setClear`/`setRain`/`setThunder` walks — the literal words the
    /// register's three branches carry, the level pair the vanilla's
    /// own weather walk banks: the clear the dry sky wears, the rain
    /// the rain level alone arms, the thunder the rain AND the thunder
    /// both speak — the unknown word the parse failure keeps).
    fn weather_levels(word: &str) -> Option<(f32, f32)> {
        match word {
            "clear" => Some((0.0, 0.0)),
            "rain" => Some((1.0, 0.0)),
            "thunder" => Some((1.0, 1.0)),
            _ => None,
        }
    }

    /// THE OFFLINE WEATHER APPLY (the active world's own level pair —
    /// the `rain_level`/`thunder_level` fields the weather render
    /// (`weather::extract_columns`) and the rain-sound clock
    /// (`ClientLevel.rainSoundTime`'s raining gate) read: the set the
    /// RAIN the visible columns and the splash voices serve). The
    /// weather CYCLE (the RAIN_DELAY/RAIN_DURATION IntProvider
    /// scheduler the ServerLevel ticks) the offline world the honest
    /// absence never carries — the levels the set-and-stay the
    /// command's own walk banks.
    fn set_offline_weather(&mut self, rain: f32, thunder: f32) {
        if let Some(w) = self.active_world_mut() {
            w.rain_level = rain;
            w.thunder_level = thunder;
        }
    }

    /// THE RED ERROR (the command.unknown.command key the lang table
    /// renders, the §c the ChatFormatting RED prefix rides — the chat
    /// draw's own § walk colors it).
    fn push_local_command_error(&mut self) {
        let msg = tr("command.unknown.command")
            .unwrap_or("Unknown or incomplete command. See below for error");
        self.push_chat_message(format!("\u{a7}c{msg}"));
    }

    /// THE RECENT DEQUE (javap ChatComponent.addRecentChat — the
    /// consecutive duplicate the skip keeps, the 100 cap the
    /// removeFirst overflow answers).
    pub fn add_recent_chat(&mut self, s: String) {
        if self.recent_chat.last().map(|l| l == &s) != Some(true) {
            self.recent_chat.push(s);
        }
        while self.recent_chat.len() > 100 {
            self.recent_chat.remove(0);
        }
    }

    /// THE DISPLAY QUEUE (javap ChatComponent.addMessage →
    /// addMessageToDisplayQueue → refreshTrimmedMessages — the
    /// (text, addedTime) pair the GuiMessage law keeps, the wrap the
    /// 320px chat width the draw re-walks, the 100-message cap the
    /// trim overflow answers).
    pub fn push_chat_message(&mut self, s: String) {
        self.chat_messages.push((s, self.frame as u32));
        while self.chat_messages.len() > 100 {
            self.chat_messages.remove(0);
        }
    }

    /// THE RELOAD CHUNKS' OWN CHORD (javap 26.2
    /// KeyboardHandler.handleDebugKeys's keyDebugReloadChunk lane —
    /// the `matches` arm pc 101 the hdk_262.txt walk banks, the
    /// handleDebugKeys' FIRST lane the ladder's own head wears (101
    /// < 130 hitboxes < 199 clearChat < 229 borders < 298 tooltips
    /// < 351 copy the pc order speaks), the NO-GUARD body the
    /// copy-recreate's player-null arm the neighbor never keeps).
    /// THE BODY (reloadchunks_170.py the walk banks): the
    /// `levelExtractor.allChanged()` walk pc 111-118 the FULL
    /// re-extract banks — every section the walk re-speaks, the mesh
    /// store the rebuild repairs (the stale mesh the chat-open
    /// refresh's screen gate ships — live_view_updated's
    /// `screen == World` check the shipped world the mesh walk never
