        let mut list = String::new();
        for i in order {
            list.push_str(&format!(
                "{}\tx={}\ty={}\tw={}\th={}\n",
                atlas::TILE_NAMES[i],
                (i % COLS) * ts,
                (i / COLS) * ts,
                ts,
                ts
            ));
        }
        let _ = std::fs::write(dir.join("minecraft_blocks.txt"), list);
        // THE YELLOW WORD (pc 883-899 — the relative path the
        // literal UNDERLINE the arg keeps, the yellow the feedback
        // channel wears)
