    /// truth the discard rides.
    pub fn live_thrown_shatter_events_updated(
        &mut self,
        events: Vec<crate::world_view::WireThrownShatterEvent>,
    ) {
        for ev in events {
            // THE SIM POSE'S OWN ANCHOR (the client copy the vanilla
            // walk runs on): the sim'd shot the id lookup names the
            // discard banks — the ALREADY-BROKEN one the silence keeps
            // (the sim's own ray the shards already spoke), the
            // unknown id the store's pose the fallback keeps (the
            // vanilla `level.getEntity` the model's store already
            // answered — the arm only banks the entity's own body).
            let (ax, ay, az) = match self.net_thrown.iter_mut().find(|t| t.id == ev.entity_id) {
                Some(t) if !t.dead => {
                    let (px, py, pz) = (t.x, t.y, t.z);
                    t.dead = true;
                    (px, py, pz)
                }
                Some(_) => continue,
                None => (ev.x, ev.y, ev.z),
            };
            // THE SHATTER'S OWN BURSTS (the same case-3 walk the net
            // sim's break lane rides — the snowball the 8 plain
            // shards, the egg the 10-jitter loop the gaussian trio's
            // x0.02 wears)
            if ev.snowball {
                for _ in 0..8 {
                    let shard =
                        crate::particles::breaking_snowball_shard(ax, ay, az, &mut self.mob_rng);
                    self.particles.push(shard);
                }
                continue;
            }
            for _ in 0..10 {
                let jx = ax + (self.mob_rng.next_f64() * 2.0 - 1.0) * 0.25;
                let jy = ay + self.mob_rng.next_f64() * 0.25;
                let jz = az + (self.mob_rng.next_f64() * 2.0 - 1.0) * 0.25;
                let wvx = self.mob_rng.next_gaussian() * 0.02;
                let wvy = self.mob_rng.next_gaussian() * 0.02;
                let wvz = self.mob_rng.next_gaussian() * 0.02;
                let shard = crate::particles::breaking_egg_shard(
                    jx,
                    jy,
                    jz,
                    wvx,
                    wvy,
                    wvz,
                    &mut self.mob_rng,
                );
                self.particles.push(shard);
            }
        }
        // THE DISCARD'S OWN SWEEP (the dead flags the retain drops —
        // the server's word the lane's own population prunes)
        self.net_thrown.retain(|t| !t.dead);
    }

    /// THE WHITE-SMOKE WALK (javap the case-2010 arm verbatim — the
    /// shared `shootParticles` helper the smoke lane's own walk
    /// mirrors): the facing the `abs(irem(data, 6))` fold resolves,
    /// the ten puffs the `bipush 10` loop keeps (the same position
    /// folds the velocity the smoke lane's own walk speaks), the
    /// `shoot_white_smoke_puff` ctor the tint override the constants
    /// carry (the base's own tint draw the stream still spends — the
    /// draw chain the smoke's own helper mirrors). No sound the case
    /// speaks, no world edit the block updates own — the visual alone
    /// the broadcast renders.
    fn play_white_smoke(&mut self, x: i32, y: i32, z: i32, data: i32) {
        const STEPS: [(f64, f64, f64); 6] = [
            (0.0, -1.0, 0.0), // DOWN
            (0.0, 1.0, 0.0),  // UP
            (0.0, 0.0, -1.0), // NORTH
            (0.0, 0.0, 1.0),  // SOUTH
            (-1.0, 0.0, 0.0), // WEST
            (1.0, 0.0, 0.0),  // EAST
        ];
        // THE FACING'S OWN DECODE (from3DDataValue: `BY_3D_DATA[abs
        // (data % 6)]` — the irem the sign keeps, the abs the negative
        // words fold)
        let idx = (data % 6).unsigned_abs() as usize;
        let (dx, dy, dz) = STEPS[idx];
        for _ in 0..10 {
            let d10 = self.level_ambient_rng.next_f64() * 0.2 + 0.01;
            // THE POSITION FOLDS (the bytecode's own operand order —
            // getX() + dx*0.6 FIRST, then the +0.5 center, then the
            // +dx*0.01 step, the crosswise jitter the tail adds)
            let px = f64::from(x)
                + dx * 0.6
                + 0.5
                + dx * 0.01
                + (self.level_ambient_rng.next_f64() - 0.5) * dz * 0.5;
            let py = f64::from(y)
                + dy * 0.6
                + 0.5
                + dy * 0.01
                + (self.level_ambient_rng.next_f64() - 0.5) * dy * 0.5;
            let pz = f64::from(z)
                + dz * 0.6
                + 0.5
                + dz * 0.01
                + (self.level_ambient_rng.next_f64() - 0.5) * dx * 0.5;
            let vx = dx * d10 + self.level_ambient_rng.next_gaussian() * 0.01;
            let vy = dy * d10 + self.level_ambient_rng.next_gaussian() * 0.01;
            let vz = dz * d10 + self.level_ambient_rng.next_gaussian() * 0.01;
            let puff = crate::particles::shoot_white_smoke_puff(
                px,
                py,
                pz,
                vx,
                vy,
                vz,
                &mut self.level_ambient_rng,
            );
            self.particles.push(puff);
        }
    }

