    fn spawn_honey_particles(&mut self, count: usize) {
        let tile = particle_tile(crate::world::HONEY_BLOCK);
        if tile == mc_registry::generated::atlas::TILE_NONE {
            return; // the tile's honest absence the filter keeps
        }
        let Some(b) = self.body.as_ref() else {
            return;
        };
        let (px, py, pz) = (b.x, b.y, b.z);
        for _ in 0..count {
            let vx = ((self.level_ambient_rng.next_f32() * 2.0 - 1.0) * 0.4) as f64;
            let vy = ((self.level_ambient_rng.next_f32() * 2.0 - 1.0) * 0.4) as f64;
            let vz = ((self.level_ambient_rng.next_f32() * 2.0 - 1.0) * 0.4) as f64;
            let r_life = self.level_ambient_rng.next_f32();
            let r_size = self.level_ambient_rng.next_f32();
            let r_uo = self.level_ambient_rng.next_f32();
            let r_vo = self.level_ambient_rng.next_f32();
            self.particles.push(crate::particles::terrain(
                tile, px, py, pz, vx, vy, vz, r_life, r_size, r_uo, r_vo,
            ));
        }
    }

    /// THE PORTAL'S OWN SCREEN GATE (javap `Screen.isAllowedInPortal`
    /// the 26.2 jar pc 0-4 — the `isPauseScreen()` delegate the whole
    /// law keeps; the arms the overrides speak: the Screen DEFAULT's
    /// iconst_1 the allowed verdict banks (PauseScreen/OptionsScreen
    /// the no-override default keeps), AbstractContainerScreen's
    /// iconst_0 the container family closes, ChatScreen's iconst_0
    /// the chat closes, DeathScreen's iconst_0 the death closes):
    /// the repo's own screen map the same law wears — the FOUR
    /// container kinds the dismiss serves, the pause/options/world-
    /// options/mode-switcher families the allowed verdict keeps, the
    /// World screen the `screen == null` shape the vanilla walk
    /// consults first (the pc 38-41 ifnull the gate skips).
    fn screen_allowed_in_portal(&self) -> bool {
        !matches!(
            self.screen,
            ScreenKind::Chest
                | ScreenKind::Dispenser
                | ScreenKind::Inventory
                | ScreenKind::Crafting
                | ScreenKind::Furnace
                | ScreenKind::Beacon
        )
    }

    /// THE PORTAL'S OWN SCREEN CLOSE (javap
    /// `LocalPlayer.handlePortalTransitionEffect` pcs 44-88 — the
    /// `closeContainer()` walk the AbstractContainerScreen arm keeps
    /// (the removed() reconciliation the container's own close
    /// serves), the `setScreen((Screen) null)` the tail speaks): the
    /// four container kinds the Escape lane's own close walks keep
    /// (the chest's close echo the ContainerClose packet the live
    /// lane speaks, the carried's return the removed() walk serves),
    /// the non-container screens the gate never reaches.
    fn portal_screen_dismiss(&mut self) {
        match self.screen {
            ScreenKind::Chest => {
                // the container's own close (the Escape lane's walk the
                // shared close speaks — the echo, the carried return,
                // the store flush, the lid release)
                self.close_chest_container(ScreenKind::World);
            }
            ScreenKind::Dispenser => self.close_dispenser(ScreenKind::World),
            ScreenKind::Brewing => self.close_brewing(ScreenKind::World),
            ScreenKind::Enchanting => self.close_enchanting(ScreenKind::World),
            ScreenKind::Anvil => self.close_anvil(ScreenKind::World),
            ScreenKind::Furnace => self.close_furnace(ScreenKind::World),
            ScreenKind::Beacon => self.close_beacon(ScreenKind::World),
            ScreenKind::Inventory => self.close_inventory(ScreenKind::World),
            ScreenKind::Creative => self.close_creative_picker(ScreenKind::World),
            ScreenKind::Crafting => self.close_crafting_table(ScreenKind::World),
            _ => {}
        }
    }

