    fn render_mouse_settings(&mut self, g: &mut Gui, a: &mut GuiAssets, w: i32, h: i32) {
        for y in 0..h {
            let t = y as f32 / h.max(1) as f32;
            let c = [0.10 + 0.04 * t, 0.10 + 0.04 * t, 0.13 + 0.05 * t];
            g.fill(0, y, w, 1, [c[0], c[1], c[2], 1.0]);
        }
        g.text_centered(
            a,
            w / 2,
            12,
            tr("options.mouse_settings.title").unwrap_or("Mouse Settings"),
            WHITE,
            true,
        );
        let cx = w / 2;
        let bw = 140;
        let bool_caption = |label: &str, on: bool| -> String {
            format!(
                "{}: {}",
                tr(label).unwrap_or(label),
                if on {
                    tr("options.on").unwrap_or("ON")
                } else {
                    tr("options.off").unwrap_or("OFF")
                }
            )
        };
        // THE (0,1) PAIR'S OWN SEATS (the addSmall's two-per-row law —
        // the LEFT the `cx - 4 - bw/2` center wears, the RIGHT the
        // `cx + 4 + bw/2` the same gap keeps, the row pitch the
        // 24-step grid the Controls pairs wear)
        let mut sens = Button::new(
            "opt_ms_sensitivity",
            sensitivity_caption(self.look_sensitivity),
            cx - 4 - bw / 2,
            h / 2 - 64,
            bw,
        );
        sens.value = Some(self.look_sensitivity);
        // THE FOCUS FLAGS' OWN RE-WEAR (the 241 two-sprite laws the
        // live seat answers — the focused track frame the grab arms)
        sens.focused = self.options_focus == Some("opt_ms_sensitivity");
        sens.can_change_value = self.options_grab && sens.focused;
        self.buttons.push(sens);
        // THE WHEEL'S OWN SLIDER (the array's index-1 seat the
        // IntRange(-200, 100) the xmap's log-scale wears — the slider's
        // own unit the unlogMouse fold answers, the caption the
        // `options.multiplier` "%sx" law the java double speaks)
        let mut wheel = Button::new(
            "opt_ms_wheel",
            format!(
                "{}: {}x",
                tr("options.mouseWheelSensitivity").unwrap_or("Scroll Sensitivity"),
                crate::options_file::java_double(self.mouse_wheel_sensitivity)
            ),
            cx + 4 + bw / 2,
            h / 2 - 64,
            bw,
        );
        wheel.value = Some(wheel_unit(self.mouse_wheel_sensitivity));
        // THE FOCUS FLAGS' OWN RE-WEAR (the same two-sprite laws the
        // wheel row answers)
        wheel.focused = self.options_focus == Some("opt_ms_wheel");
        wheel.can_change_value = self.options_grab && wheel.focused;
        self.buttons.push(wheel);
        // THE (2,3) PAIR'S OWN SEATS (the discrete/invertX rows the
        // createBoolean captions wear)
        self.buttons.push(Button::new(
            "opt_ms_discrete",
            bool_caption("options.discrete_mouse_scroll", self.discrete_mouse_scroll),
            cx - 4 - bw / 2,
            h / 2 - 40,
            bw,
        ));
        self.buttons.push(Button::new(
            "opt_ms_invertx",
            bool_caption("options.invertMouseX", self.invert_mouse_x),
            cx + 4 + bw / 2,
            h / 2 - 40,
            bw,
        ));
        // THE (4,5) PAIR'S OWN SEATS (the invertY/allowCursor rows the
        // same boolean law wears)
        self.buttons.push(Button::new(
            "opt_ms_inverty",
            bool_caption("options.invertMouseY", self.invert_mouse_y),
            cx - 4 - bw / 2,
            h / 2 - 16,
            bw,
        ));
        self.buttons.push(Button::new(
            "opt_ms_allowcursor",
            bool_caption("options.allowCursorChanges", self.allow_cursor_changes),
            cx + 4 + bw / 2,
            h / 2 - 16,
            bw,
        ));
        // THE RAW INPUT'S OWN ROW (the addOptions walk's appended tail
        // the odd-one LEFT seat wears — the (6, —) pair the single row
        // the operator-tab row's own law keeps)
        self.buttons.push(Button::new(
            "opt_ms_rawinput",
            bool_caption("options.rawMouseInput", self.raw_mouse_input),
            cx - 4 - bw / 2,
            h / 2 + 8,
            bw,
        ));
        self.buttons.push(Button::new(
            "msdone",
            tr("gui.done").unwrap_or("Done").to_string(),
            cx,
            h - 28,
            bw,
        ));
        // THE FOCUSED FLAGS' OWN RE-WEAR (the isHoveredOrFocused law
        // the focused seat lights — the one sweep the ALL rows' flag
        // wears: the Tab-ride/plain-claim seat the frame banks, the
        // slider rows' build sites the same value the
        // can_change_value keeps, the stale seat the flags clear)
        if let Some(id) = self.options_focus {
            for b in self.buttons.iter_mut() {
                b.focused = b.id == id;
            }
        }
        for b in &self.buttons.clone() {
            b.render(g, a, -1, -1);
        }
    }

    /// THE COMPARETO'S OWN RE-SEAT (the KeyBindsList ctor's
    /// `Arrays.sort` walk the vanilla law wears — the
    /// `KeyMapping.compareTo` the three-key ladder answers: the
    /// category the SORT_ORDER ordinal the group boundaries the
    /// render's own seats keep, the orderI the WITHIN-group primary
    /// the ORDER_I bank wears, the TIES the `I18n.get(name)`
    /// compareTo the alphabetical secondary answers — the orderI=0
    /// rows the re-seat wear, the registration order the sort never
    /// speaks, the tr() row the I18n.get law the same string the
    /// row renders the compare keeps)
    ///
    /// THE SORT-KEY CACHE (the vanilla ctor's own once-ness — the
    /// Arrays.sort the KeyBindsList <init> speaks ONCE, the list the
    /// rows the sorted array carries, the rebind the bound key alone
    /// re-wears the sort position never re-answers): the per-frame
    /// render walk's seven group sorts the ONE process-lifetime
    /// static table answers — [`Self::kb_seated_full`] the full
    /// 0..COUNT order the same comparator banks once, the group
    /// seats the static's own filter the rows wear. THE STABLE-SORT
    /// THEOREM the equivalence carries: the Rust `sort_by` the
    /// stable law keeps, the full walk's input 0..COUNT ascending
    /// AND the group walk's input lo..hi ascending the SAME relative
    /// input order the equal keys preserve — the within-group
    /// relative order the comparator outcome alone answers, the
    /// filter the order carries verbatim, the seven call sites the
    /// same Vec the exact sort's own result wear. The comparator's
    /// own inputs the process-lifetime constants keep (ORDER_I the
    /// const array, NAMES/NAME_FALLBACKS the consts, tr() the
    /// OnceLock en_us table the same determinism the whole client
    /// wears) — the static the vanilla ctor's once-ness the honest
    /// shape serves.
    fn kb_seated(lo: usize, hi: usize) -> Vec<usize> {
        Self::kb_seated_full()
            .iter()
            .copied()
            .filter(|i| *i >= lo && *i < hi)
            .collect()
    }

    /// THE STATIC TABLE'S OWN SEAT (the sort-key cache's once walk —
    /// the full 0..COUNT order the [`Self::kb_seated`] comparator the
    /// exact same fold computes, the get_or_init the second read the
    /// sort never re-answers)
    fn kb_seated_full() -> &'static Vec<usize> {
        use crate::options_file::key_binds as kb;
        static SEATED: std::sync::OnceLock<Vec<usize>> = std::sync::OnceLock::new();
        SEATED.get_or_init(|| {
            let mut rows: Vec<usize> = (0..kb::COUNT).collect();
            rows.sort_by(|&a, &b| {
                kb::ORDER_I[a].cmp(&kb::ORDER_I[b]).then_with(|| {
                    let na = tr(kb::NAMES[a]).unwrap_or(kb::NAME_FALLBACKS[a]);
                    let nb = tr(kb::NAMES[b]).unwrap_or(kb::NAME_FALLBACKS[b]);
                    na.cmp(nb)
                })
            });
            rows
        })
    }

